const req = $('Webhook tìm sách').first().json;
const headers = req.headers || {};
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
let cfg = $input.first().json.cfg || {};
if (typeof cfg === 'string') cfg = JSON.parse(cfg);

const posInt = (v, d) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : d;
};

const expected = String(cfg.biascan_token || '').trim();
const given = String(headers['x-biascan-token'] || '').trim();
const auth_ok = expected !== '' && given === expected;
const auth_message = expected === ''
  ? 'Máy chủ chưa cấu hình biascan_token trong bảng app_config.'
  : 'Thiếu hoặc sai header x-biascan-token.';

// n8n.thuanbt.id.vn chạy sau Fly proxy: chỉ fly-client-ip do proxy đặt; cf-connecting-ip / x-forwarded-for client tự gửi được.
const forwarded = String(headers['x-forwarded-for'] || '').split(',')[0].trim();
const ip = String(headers['fly-client-ip'] || '').trim()
  || String(headers['cf-connecting-ip'] || '').trim() || forwarded || 'unknown';

const MAX_IMAGE_BYTES = 4 * 1024 * 1024;
const IMAGE_MIMES = ['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'];

let input_error = '';
const query = typeof body.query === 'string' ? body.query.replace(/\s+/g, ' ').trim() : '';
const session_id = typeof body.session_id === 'string' ? body.session_id.trim() : '';
let image_mime = '';
let image_b64 = '';

if (body.query !== undefined && body.query !== null && typeof body.query !== 'string') {
  input_error = 'Trường query phải là chuỗi.';
} else if (query.length > 1000) {
  input_error = 'Mô tả quá dài (tối đa 1000 ký tự).';
}

if (!input_error && typeof body.image === 'string' && body.image.trim() !== '') {
  const raw = body.image.trim();
  const m = raw.match(/^data:([a-z0-9.+\/-]+);base64,(.*)$/is);
  image_mime = m ? m[1].toLowerCase() : 'image/jpeg';
  image_b64 = (m ? m[2] : raw).replace(/\s+/g, '');
  if (image_mime === 'image/jpg') image_mime = 'image/jpeg';
  const padding = image_b64.endsWith('==') ? 2 : image_b64.endsWith('=') ? 1 : 0;
  const bytes = Math.floor((image_b64.length * 3) / 4) - padding;
  if (!IMAGE_MIMES.includes(image_mime)) {
    input_error = 'Định dạng ảnh không hỗ trợ (chỉ nhận JPEG, PNG, WEBP, HEIC).';
  } else if (!/^[A-Za-z0-9+/]+={0,2}$/.test(image_b64)) {
    input_error = 'Ảnh không phải base64 hợp lệ.';
  } else if (bytes > MAX_IMAGE_BYTES) {
    input_error = 'Ảnh lớn hơn 4 MB, hãy nén lại trước khi gửi.';
  }
} else if (!input_error && body.image !== undefined && body.image !== null && typeof body.image !== 'string') {
  input_error = 'Trường image phải là chuỗi data URL base64.';
}

if (!input_error && !session_id) input_error = 'Thiếu session_id.';
else if (!input_error && session_id.length > 200) input_error = 'session_id quá dài.';
if (!input_error && !query && !image_b64) input_error = 'Cần ít nhất một trong hai: query hoặc image.';

const has_image = !input_error && image_b64 !== '';

return [{
  json: {
    t_start: Date.now(),
    auth_ok,
    auth_message,
    ip,
    input_error,
    query,
    session_id,
    has_image,
    image_mime: has_image ? image_mime : '',
    image_b64: has_image ? image_b64 : '',
    cfg: {
      ocr_model: String(cfg.ocr_model || 'gemini-flash-latest').trim(),
      chat_model: String(cfg.chat_model || 'gemini-flash-latest').trim(),
      embed_model: String(cfg.embed_model || 'gemini-embedding-2').trim(),
      embed_dims: posInt(cfg.embed_dims, 768),
      top_k: Math.min(posInt(cfg.top_k, 10), 50),
      rerank_k: Math.min(posInt(cfg.rerank_k, 3), 10),
      per_min: posInt(cfg.rate_limit_per_min, 10),
      per_day: posInt(cfg.rate_limit_per_day, 200),
      image_search_enabled: String(cfg.image_search_enabled || '').trim().toLowerCase() === 'true',
    },
  },
}];

const ctx = $('Kiểm tra token và đầu vào').first().json;
const prompt = [
  'Ảnh là bìa trước của một cuốn sách, có thể bị nghiêng, mờ, lóa hoặc che một phần.',
  'Đọc chữ trên bìa và trả về JSON với các trường:',
  '- title: tên sách đúng nguyên văn trên bìa (giữ dấu tiếng Việt), chuỗi rỗng nếu không đọc được;',
  '- author: tác giả / dịch giả nếu thấy, chuỗi rỗng nếu không;',
  '- publisher: nhà xuất bản hoặc đơn vị phát hành (logo, chữ nhỏ) nếu thấy, chuỗi rỗng nếu không;',
  '- other_text: chữ đáng chú ý khác như phụ đề, tên bộ sách, tối đa 200 ký tự.',
  'Chỉ ghi chữ thực sự có trên ảnh, không đoán, không bịa.',
].join('\n');

const str = { type: 'STRING' };
return [{
  json: {
    ...ctx,
    t_ocr: Date.now(),
    ocr_request: {
      contents: [{
        role: 'user',
        parts: [
          { inlineData: { mimeType: ctx.image_mime, data: ctx.image_b64 } },
          { text: prompt },
        ],
      }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties: { title: str, author: str, publisher: str, other_text: str },
          required: ['title', 'author', 'publisher', 'other_text'],
        },
      },
    },
  },
}];

const { ocr_request, ...ctx } = $('Chuẩn bị OCR').first().json;
const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
const text = parts.filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('');

let ocr = {};
try {
  ocr = JSON.parse(text);
} catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) {
    try { ocr = JSON.parse(m[0]); } catch (e2) { ocr = {}; }
  }
}

const clean = (v) => (typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : '');
const title = clean(ocr.title);
const lines = [];
if (title) lines.push(`Tên sách: ${title}`);
if (clean(ocr.author)) lines.push(`Tác giả: ${clean(ocr.author)}`);
if (clean(ocr.publisher)) lines.push(`Nhà xuất bản: ${clean(ocr.publisher)}`);
if (clean(ocr.other_text)) lines.push(clean(ocr.other_text).slice(0, 200));

return [{
  json: {
    ...ctx,
    ocr_text: lines.length ? lines.join('\n') : null,
    ocr_title: title,
    ocr_ms: Date.now() - ctx.t_ocr,
  },
}];

const ctx = $input.first().json;
const norm = (s) => String(s || '')
  .replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/\p{Mn}/gu, '').normalize('NFC')
  .toLowerCase().replace(/\s+/g, ' ').trim();

const query_text = [ctx.ocr_text, ctx.query].filter(Boolean).join('\n');
const query_norm = norm(ctx.ocr_title || ctx.query);
const request = {
  content: { parts: [{ text: ctx.cfg.embed_model.startsWith('gemini-embedding-2') ? `task: search result | query: ${query_text}` : query_text }] },
  outputDimensionality: ctx.cfg.embed_dims,
};
// gemini-embedding-2 từ chối taskType; model cũ (gemini-embedding-001...) thì dùng RETRIEVAL_QUERY.
if (!ctx.cfg.embed_model.startsWith('gemini-embedding-2')) request.taskType = 'RETRIEVAL_QUERY';

return [{
  json: {
    ...ctx,
    query_text,
    query_norm,
    has_text: query_text.trim() !== '',
    do_image_embed: Boolean(ctx.has_image && ctx.cfg.image_search_enabled),
    embed_request: request,
    t_embed: Date.now(),
  },
}];

const { embed_request, ...ctx } = $('Chuẩn bị embed').first().json;
const values = $input.first().json.embedding?.values;
if (!Array.isArray(values) || values.length !== ctx.cfg.embed_dims) {
  throw new Error(`Embedding câu hỏi sai số chiều: ${Array.isArray(values) ? values.length : 'không có'} (cần ${ctx.cfg.embed_dims})`);
}
const now = Date.now();
const out = {
  ...ctx,
  text_vec: `[${values.join(',')}]`,
  embed_ms: now - ctx.t_embed,
  t_search: now,
};
if (!ctx.do_image_embed) {
  out.image_b64 = '';
}
return [{ json: out }];

const ctx = $('Nhận vector câu hỏi').first().json;
const values = $input.first().json.embedding?.values;
if (!Array.isArray(values) || values.length !== ctx.cfg.embed_dims) {
  throw new Error(`Embedding ảnh sai số chiều: ${Array.isArray(values) ? values.length : 'không có'} (cần ${ctx.cfg.embed_dims})`);
}
const now = Date.now();
return [{
  json: {
    ...ctx,
    image_b64: '',
    image_vec: `[${values.join(',')}]`,
    embed_ms: now - ctx.t_embed,
    t_search: now,
  },
}];

const viaImage = $('Nhận vector ảnh').isExecuted;
const { text_vec, image_vec, image_b64, ...ctx } = viaImage
  ? $('Nhận vector ảnh').first().json
  : $('Nhận vector câu hỏi').first().json;
const now = Date.now();

let rows = $input.first().json.rows;
if (typeof rows === 'string') rows = JSON.parse(rows);
if (!Array.isArray(rows)) rows = [];

const s = (v) => (typeof v === 'string' ? v : v == null ? '' : String(v));
const hits = rows.map((r) => ({
  image_id: s(r.image_id),
  title: s(r.title),
  author: s(r.author),
  publisher: s(r.publisher),
  supplier: s(r.supplier),
  image_url: s(r.image_url),
  product_url: s(r.product_url),
  score: Number(r.score) || 0,
  description: s(r.description).replace(/\s+/g, ' ').trim(),
})).filter((h) => h.image_id);

const rerankK = Math.min(ctx.cfg.rerank_k, hits.length);
const need = [ctx.query ? `Mô tả của khách: ${ctx.query}` : '', ctx.ocr_text ? `Chữ đọc được trên ảnh bìa khách chụp:\n${ctx.ocr_text}` : '']
  .filter(Boolean).join('\n\n');
const list = hits.map((h) => `[${h.image_id}] ${h.title} | Tác giả: ${h.author || '-'} | NXB: ${h.publisher || '-'}\n   ${h.description.slice(0, 300)}`).join('\n');
const prompt = [
  'Bạn là chuyên viên nhà sách. Khách đang tìm sách với thông tin sau:',
  need || '(không có mô tả)',
  '',
  'Danh sách ứng viên từ kho sách:',
  list,
  '',
  `Chọn tối đa ${rerankK} cuốn khớp nhất với nhu cầu của khách, xếp theo mức độ khớp giảm dần.`,
  'Nếu có chữ đọc từ ảnh bìa thì ưu tiên cuốn trùng tên sách / tác giả với chữ đó.',
  'Mỗi cuốn kèm reason: lý do ngắn bằng tiếng Việt (tối đa 25 từ), chỉ dựa vào thông tin trong danh sách.',
  'Chỉ dùng image_id có trong danh sách, không bịa thêm.',
].join('\n');

return [{
  json: {
    t_start: ctx.t_start,
    ocr_text: ctx.ocr_text,
    top_k: ctx.cfg.top_k,
    rerank_k: rerankK,
    need_rerank: rerankK > 0,
    chat_model: ctx.cfg.chat_model,
    timings: { ocr: ctx.ocr_ms, embed: ctx.embed_ms, search: now - ctx.t_search },
    hits: hits.map(({ description, ...card }) => card),
    rerank_request: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties: {
            ranked: {
              type: 'ARRAY',
              items: {
                type: 'OBJECT',
                properties: { image_id: { type: 'STRING' }, reason: { type: 'STRING' } },
                required: ['image_id', 'reason'],
              },
            },
          },
          required: ['ranked'],
        },
      },
    },
    t_rerank: Date.now(),
  },
}];

const ctx = $('Gom ứng viên').first().json;
const now = Date.now();
const byId = new Map(ctx.hits.map((h) => [h.image_id, h]));
const order = [];
const reasons = new Map();
let rerank_ms = 0;

if (ctx.need_rerank) {
  rerank_ms = now - ctx.t_rerank;
  const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
  const text = parts.filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('');
  let ranked = [];
  try {
    const parsed = JSON.parse(text);
    ranked = Array.isArray(parsed) ? parsed : Array.isArray(parsed.ranked) ? parsed.ranked : [];
  } catch (e) {
    ranked = [];
  }
  for (const r of ranked) {
    const id = typeof r?.image_id === 'string' ? r.image_id.trim().replace(/^\[|\]$/g, '') : '';
    if (!byId.has(id) || reasons.has(id) || order.length >= ctx.rerank_k) continue;
    order.push(id);
    const reason = typeof r.reason === 'string' ? r.reason.trim() : '';
    reasons.set(id, reason || null);
  }
}

const picked = new Set(order);
const merged = [...order.map((id) => byId.get(id)), ...ctx.hits.filter((h) => !picked.has(h.image_id))];
const results = merged.slice(0, ctx.top_k).map((h) => ({
  ...h,
  score: Math.round(h.score * 10000) / 10000,
  reason: reasons.get(h.image_id) ?? null,
}));

return [{
  json: {
    ocr_text: ctx.ocr_text,
    results,
    timings_ms: { ...ctx.timings, rerank: rerank_ms, total: now - ctx.t_start },
  },
}];

const req = $('Webhook chat').first().json;
const headers = req.headers || {};
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
let cfg = $input.first().json.cfg || {};
if (typeof cfg === 'string') cfg = JSON.parse(cfg);

const posInt = (v, d) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : d;
};

const expected = String(cfg.biascan_token || '').trim();
const given = String(headers['x-biascan-token'] || '').trim();
const auth_ok = expected !== '' && given === expected;
const auth_message = expected === ''
  ? 'Máy chủ chưa cấu hình biascan_token trong bảng app_config.'
  : 'Thiếu hoặc sai header x-biascan-token.';

// n8n.thuanbt.id.vn chạy sau Fly proxy: chỉ fly-client-ip do proxy đặt; cf-connecting-ip / x-forwarded-for client tự gửi được.
const forwarded = String(headers['x-forwarded-for'] || '').split(',')[0].trim();
const ip = String(headers['fly-client-ip'] || '').trim()
  || String(headers['cf-connecting-ip'] || '').trim() || forwarded || 'unknown';

const session_id = typeof body.session_id === 'string' ? body.session_id.trim() : '';
const message = typeof body.message === 'string' ? body.message.trim() : '';
let context_ids = [];
let input_error = '';

if (!session_id) input_error = 'Thiếu session_id.';
else if (session_id.length > 200) input_error = 'session_id quá dài.';
else if (!message) input_error = 'Thiếu message.';
else if (message.length > 2000) input_error = 'Tin nhắn quá dài (tối đa 2000 ký tự).';
else if (body.context_ids !== undefined && body.context_ids !== null) {
  if (!Array.isArray(body.context_ids) || body.context_ids.some((id) => typeof id !== 'string')) {
    input_error = 'context_ids phải là mảng chuỗi.';
  } else {
    context_ids = [...new Set(body.context_ids.map((id) => id.trim()).filter(Boolean))].slice(0, 20);
  }
}

return [{
  json: {
    auth_ok,
    auth_message,
    ip,
    input_error,
    session_id,
    message,
    context_ids,
    cfg: {
      chat_model: String(cfg.chat_model || 'gemini-flash-latest').trim(),
      per_min: posInt(cfg.rate_limit_per_min, 10),
      per_day: posInt(cfg.rate_limit_per_day, 200),
    },
  },
}];

parameters.query:
select coalesce(json_agg(json_build_object(
  'image_id', b.image_id, 'title', b.title, 'author', b.author, 'publisher', b.publisher
) order by x.ord), '[]'::json) as books
from jsonb_array_elements_text($1::jsonb) with ordinality as x(id, ord)
join public.books b on b.image_id = x.id;

