const ctx = $('Chat: Kiểm tra token và đầu vào').first().json;
let books = $input.first().json.books;
if (typeof books === 'string') books = JSON.parse(books);
if (!Array.isArray(books)) books = [];

const lines = books.map((b) => `- [${b.image_id}] ${b.title}${b.author ? ` — ${b.author}` : ''}${b.publisher ? ` (${b.publisher})` : ''}`);
const chat_input = lines.length
  ? `Sách khách đang xem trên trang:\n${lines.join('\n')}\n\nTin nhắn của khách: ${ctx.message}`
  : ctx.message;

return [{
  json: {
    session_id: ctx.session_id,
    chat_model: ctx.cfg.chat_model,
    chat_input,
  },
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "reply": {
      "type": "string",
      "description": "Câu trả lời markdown tiếng Việt"
    },
    "suggestions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "2-3 câu hỏi tiếp theo gợi ý cho khách"
    },
    "products": {
      "type": "array",
      "description": "Sách được nhắc trong reply, image_id lấy từ kết quả tim_sach",
      "items": {
        "type": "object",
        "properties": {
          "image_id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          }
        },
        "required": [
          "image_id",
          "title"
        ]
      }
    }
  },
  "required": [
    "reply",
    "suggestions",
    "products"
  ]
}

